package com.gameaggregator.authorizationservice.api;import com.gameaggregator.authorizationservice.application.AuthorizationService;import com.gameaggregator.platform.core.common.web.ApiResponse;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpHeaders;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/authorization") public class AuthorizationController{private final AuthorizationService service;public AuthorizationController(AuthorizationService s){service=s;}@PostMapping("/check")public ApiResponse<AuthorizationDtos.AuthorizationDecision> check(@AuthenticationPrincipal Jwt jwt,@RequestHeader(HttpHeaders.AUTHORIZATION)String bearer,@Valid @RequestBody AuthorizationDtos.AuthorizationRequest request){return ApiResponse.success(service.check(UUID.fromString(jwt.getSubject()),request,bearer));}}
